import zipfile, xml.etree.ElementTree as ET, re
z=zipfile.ZipFile('budget.xlsx')
L=lambda t:t.split('}')[-1]
def rd(p): return ET.fromstring(z.read(p))
ss={}
if 'xl/sharedStrings.xml' in z.namelist():
    r=rd('xl/sharedStrings.xml'); i=0
    for si in r.iter():
        if L(si.tag)=='si':
            ss[i]=''.join(t.text or '' for t in si.iter() if L(t.tag)=='t'); i+=1
wb=rd('xl/workbook.xml'); rels=rd('xl/_rels/workbook.xml.rels')
rm={r.get('Id'):r.get('Target') for r in rels if L(r.tag)=='Relationship'}
for sh in wb.iter():
    if L(sh.tag)=='sheet':
        nm=sh.get('name')
        rid=[v for k,v in sh.attrib.items() if L(k)=='id'][0]
        tg=rm[rid]
        if not tg.startswith('xl/'): tg='xl/'+tg.lstrip('/')
        print('=== SHEET:',nm,'===')
        root=rd(tg)
        for row in root.iter():
            if L(row.tag)=='row':
                cells={}
                for c in row:
                    if L(c.tag)!='c': continue
                    ref=c.get('r'); t=c.get('t')
                    vs=[e for e in c if L(e.tag)=='v']
                    val=None
                    if vs and vs[0].text is not None:
                        txt=vs[0].text
                        if t=='s': val=ss.get(int(txt))
                        else: val=txt
                    col=re.match(r'[A-Z]+',ref).group()
                    cells[col]=val
                if cells:
                    cols=sorted(cells)
                    print(' | '.join(str(cells.get(k,'')) for k in cols))
"

